-- 517: Foundation guard for NSMQ question bank expansion beta batch 002.
-- Original BrillaPrep practice content; not official NSMQ (Primetime) material.
-- Also seeds the prod-canonical per-subject NSMQ topic rows (copied from the legacy
-- seed-style rows) for fresh baselines; INSERT OR IGNORE no-ops on prod where they exist.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS question_content_releases (
    question_id TEXT PRIMARY KEY REFERENCES questions(id) ON DELETE CASCADE,
    batch_id TEXT NOT NULL,
    quality_assurance TEXT NOT NULL CHECK (quality_assurance IN ('automated_beta', 'human_reviewed')),
    release_channel TEXT NOT NULL CHECK (release_channel IN ('beta', 'production')),
    content_label TEXT NOT NULL,
    source_url TEXT NOT NULL,
    official_exam_board_content INTEGER NOT NULL DEFAULT 0 CHECK (official_exam_board_content IN (0, 1)),
    feedback_enabled INTEGER NOT NULL DEFAULT 1 CHECK (feedback_enabled IN (0, 1)),
    released_at TEXT NOT NULL DEFAULT (datetime('now'))
  );
CREATE INDEX IF NOT EXISTS idx_question_content_releases_batch ON question_content_releases(batch_id);
INSERT OR IGNORE INTO topics (id, subject_id, parent_id, name, slug, description, theory_content, key_formulas, display_order, created_at) VALUES ('topic_nsmq_math_algebra', 'subj_nsmq_math', NULL, 'Algebra', 'nsmq-math-algebra', 'Fundamental algebraic concepts and operations', 'Algebra is the branch of mathematics dealing with symbols and the rules for manipulating those symbols. It includes solving equations, working with polynomials, and understanding functions.', '["ax + b = c → x = (c-b)/a", "(a+b)² = a² + 2ab + b²", "(a-b)² = a² - 2ab + b²", "a² - b² = (a+b)(a-b)"]', 1, '2026-08-04T00:00:00.000Z');
INSERT OR IGNORE INTO topics (id, subject_id, parent_id, name, slug, description, theory_content, key_formulas, display_order, created_at) VALUES ('topic_nsmq_math_calculus', 'subj_nsmq_math', NULL, 'Calculus', 'nsmq-math-calculus', 'Study of rates of change and accumulation', 'Calculus is the mathematical study of continuous change. It has two major branches: differential calculus and integral calculus.', '["d/dx(xⁿ) = nxⁿ⁻¹", "∫xⁿdx = xⁿ⁺¹/(n+1) + C", "d/dx(sin x) = cos x", "d/dx(eˣ) = eˣ"]', 4, '2026-08-04T00:00:00.000Z');
INSERT OR IGNORE INTO topics (id, subject_id, parent_id, name, slug, description, theory_content, key_formulas, display_order, created_at) VALUES ('topic_nsmq_math_geometry', 'subj_nsmq_math', NULL, 'Geometry', 'nsmq-math-geometry', 'Study of shapes, sizes, and properties of space', 'Geometry deals with the properties, measurement, and relationships of points, lines, angles, surfaces, and solids.', '["Area of circle = πr²", "Circumference = 2πr", "Area of triangle = ½bh", "Pythagorean theorem: a² + b² = c²"]', 2, '2026-08-04T00:00:00.000Z');
INSERT OR IGNORE INTO topics (id, subject_id, parent_id, name, slug, description, theory_content, key_formulas, display_order, created_at) VALUES ('topic_nsmq_math_statistics', 'subj_nsmq_math', NULL, 'Statistics & Probability', 'nsmq-math-statistics', 'Analysis of data and chance', 'Statistics involves collecting, analyzing, and interpreting data. Probability measures the likelihood of events occurring.', '["Mean = Σx/n", "Variance = Σ(x-μ)²/n", "P(A∪B) = P(A) + P(B) - P(A∩B)", "P(A|B) = P(A∩B)/P(B)"]', 5, '2026-08-04T00:00:00.000Z');
INSERT OR IGNORE INTO topics (id, subject_id, parent_id, name, slug, description, theory_content, key_formulas, display_order, created_at) VALUES ('topic_nsmq_math_trigonometry', 'subj_nsmq_math', NULL, 'Trigonometry', 'nsmq-math-trigonometry', 'Study of triangles and trigonometric functions', 'Trigonometry studies relationships between side lengths and angles of triangles. The main functions are sine, cosine, and tangent.', '["sin²θ + cos²θ = 1", "tan θ = sin θ / cos θ", "sin 2θ = 2 sin θ cos θ", "cos 2θ = cos²θ - sin²θ"]', 3, '2026-08-04T00:00:00.000Z');
INSERT OR IGNORE INTO topics (id, subject_id, parent_id, name, slug, description, theory_content, key_formulas, display_order, created_at) VALUES ('topic_nsmq_phys_electricity', 'subj_nsmq_physics', NULL, 'Electricity & Magnetism', 'nsmq-phys-electricity', 'Study of electric charges and magnetic fields', 'This branch covers electric charges, electric fields, magnetic fields, and electromagnetic interactions.', '["V = IR (Ohm''s Law)", "P = IV = I²R", "F = qE", "F = BIL"]', 2, '2026-08-04T00:00:00.000Z');
INSERT OR IGNORE INTO topics (id, subject_id, parent_id, name, slug, description, theory_content, key_formulas, display_order, created_at) VALUES ('topic_nsmq_phys_mechanics', 'subj_nsmq_physics', NULL, 'Mechanics', 'nsmq-phys-mechanics', 'Study of motion and forces', 'Mechanics is the branch of physics dealing with motion and the forces that produce motion. It includes kinematics, dynamics, and statics.', '["v = u + at", "s = ut + ½at²", "v² = u² + 2as", "F = ma"]', 1, '2026-08-04T00:00:00.000Z');
INSERT OR IGNORE INTO topics (id, subject_id, parent_id, name, slug, description, theory_content, key_formulas, display_order, created_at) VALUES ('topic_nsmq_phys_modern_physics', 'subj_nsmq_physics', NULL, 'Modern Physics', 'nsmq-phys-modern-physics', 'Quantum mechanics and relativity', 'Modern physics covers theories developed in the 20th century including quantum mechanics, special relativity, and atomic physics.', '["E = mc²", "E = hf", "λ = h/mv", "ΔxΔp ≥ ℏ/2"]', 5, '2026-08-04T00:00:00.000Z');
INSERT OR IGNORE INTO topics (id, subject_id, parent_id, name, slug, description, theory_content, key_formulas, display_order, created_at) VALUES ('topic_nsmq_phys_thermodynamics', 'subj_nsmq_physics', NULL, 'Thermodynamics', 'nsmq-phys-thermodynamics', 'Study of heat and energy transfer', 'Thermodynamics studies the relationships between heat, work, temperature, and energy in physical systems.', '["Q = mcΔT", "PV = nRT", "W = PΔV", "Efficiency = W/Q_in"]', 4, '2026-08-04T00:00:00.000Z');
INSERT OR IGNORE INTO topics (id, subject_id, parent_id, name, slug, description, theory_content, key_formulas, display_order, created_at) VALUES ('topic_nsmq_phys_waves', 'subj_nsmq_physics', NULL, 'Waves & Optics', 'nsmq-phys-waves', 'Study of wave motion and light', 'Waves transfer energy without transferring matter. Optics is the study of light behavior including reflection, refraction, and diffraction.', '["v = fλ", "n = c/v", "n₁sinθ₁ = n₂sinθ₂ (Snell''s Law)", "1/f = 1/u + 1/v"]', 3, '2026-08-04T00:00:00.000Z');
INSERT OR IGNORE INTO topics (id, subject_id, parent_id, name, slug, description, theory_content, key_formulas, display_order, created_at) VALUES ('topic_nsmq_chem_atomic', 'subj_nsmq_chemistry', NULL, 'Atomic Structure', 'nsmq-chem-atomic', 'Structure of atoms and electron configuration', 'Atoms consist of protons, neutrons, and electrons. Understanding electron configuration is key to predicting chemical behavior.', '["Mass number A = Z + N", "E = -13.6/n² eV (hydrogen)", "λ = h/mv (de Broglie)"]', 1, '2026-08-04T00:00:00.000Z');
INSERT OR IGNORE INTO topics (id, subject_id, parent_id, name, slug, description, theory_content, key_formulas, display_order, created_at) VALUES ('topic_nsmq_chem_bonding', 'subj_nsmq_chemistry', NULL, 'Chemical Bonding', 'nsmq-chem-bonding', 'How atoms combine to form compounds', 'Chemical bonds form when atoms share or transfer electrons. Main types include ionic, covalent, and metallic bonds.', '["Bond order = (bonding e⁻ - antibonding e⁻)/2", "Electronegativity difference determines bond type"]', 2, '2026-08-04T00:00:00.000Z');
INSERT OR IGNORE INTO topics (id, subject_id, parent_id, name, slug, description, theory_content, key_formulas, display_order, created_at) VALUES ('topic_nsmq_chem_stoichiometry', 'subj_nsmq_chemistry', NULL, 'Stoichiometry', 'nsmq-chem-stoichiometry', 'Quantitative relationships in chemical reactions', 'Stoichiometry involves calculating the quantities of reactants and products in chemical reactions using balanced equations.', '["n = m/M", "Molarity M = n/V", "PV = nRT", "% yield = (actual/theoretical) × 100"]', 3, '2026-08-04T00:00:00.000Z');
INSERT OR IGNORE INTO topics (id, subject_id, parent_id, name, slug, description, theory_content, key_formulas, display_order, created_at) VALUES ('topic_nsmq_chem_equilibrium', 'subj_nsmq_chemistry', NULL, 'Chemical Equilibrium', 'nsmq-chem-equilibrium', 'Balance in reversible reactions', 'Chemical equilibrium occurs when the rates of forward and reverse reactions are equal. Le Chatelier''s principle predicts equilibrium shifts.', '["Kc = [products]/[reactants]", "Kp = Kc(RT)^Δn", "ΔG = -RT ln K"]', 4, '2026-08-04T00:00:00.000Z');
INSERT OR IGNORE INTO topics (id, subject_id, parent_id, name, slug, description, theory_content, key_formulas, display_order, created_at) VALUES ('topic_nsmq_chem_organic', 'subj_nsmq_chemistry', NULL, 'Organic Chemistry', 'nsmq-chem-organic', 'Chemistry of carbon compounds', 'Organic chemistry studies carbon-containing compounds. It covers nomenclature, reactions, and properties of organic molecules.', '["CₙH₂ₙ₊₂ (alkanes)", "CₙH₂ₙ (alkenes)", "CₙH₂ₙ₋₂ (alkynes)"]', 5, '2026-08-04T00:00:00.000Z');
INSERT OR IGNORE INTO topics (id, subject_id, parent_id, name, slug, description, theory_content, key_formulas, display_order, created_at) VALUES ('topic_nsmq_chem_electrochemistry', 'subj_nsmq_chemistry', NULL, 'Electrochemistry', 'nsmq-chem-electrochemistry', 'Chemical reactions involving electricity', 'Electrochemistry studies the relationship between electrical energy and chemical changes, including batteries and electrolysis.', '["E°cell = E°cathode - E°anode", "ΔG = -nFE°", "Faraday''s laws"]', 6, '2026-08-04T00:00:00.000Z');
INSERT OR IGNORE INTO topics (id, subject_id, parent_id, name, slug, description, theory_content, key_formulas, display_order, created_at) VALUES ('topic_nsmq_bio_cells', 'subj_nsmq_biology', NULL, 'Cell Biology', 'nsmq-bio-cells', 'Structure and function of cells', 'The cell is the basic unit of life. Understanding cell structure and organelle functions is fundamental to biology.', '["Cell theory", "Prokaryotic vs Eukaryotic", "Organelle functions"]', 1, '2026-08-04T00:00:00.000Z');
INSERT OR IGNORE INTO topics (id, subject_id, parent_id, name, slug, description, theory_content, key_formulas, display_order, created_at) VALUES ('topic_nsmq_bio_genetics', 'subj_nsmq_biology', NULL, 'Genetics', 'nsmq-bio-genetics', 'Study of heredity and variation', 'Genetics studies how traits are passed from parents to offspring through genes and DNA.', '["Mendel''s laws", "Punnett squares", "DNA structure: A-T, G-C"]', 2, '2026-08-04T00:00:00.000Z');
INSERT OR IGNORE INTO topics (id, subject_id, parent_id, name, slug, description, theory_content, key_formulas, display_order, created_at) VALUES ('topic_nsmq_bio_ecology', 'subj_nsmq_biology', NULL, 'Ecology', 'nsmq-bio-ecology', 'Study of organisms and their environment', 'Ecology examines the relationships between organisms and their environment, including ecosystems and biodiversity.', '["Food chains/webs", "Energy flow (10% rule)", "Population dynamics"]', 3, '2026-08-04T00:00:00.000Z');
INSERT OR IGNORE INTO topics (id, subject_id, parent_id, name, slug, description, theory_content, key_formulas, display_order, created_at) VALUES ('topic_nsmq_bio_physiology', 'subj_nsmq_biology', NULL, 'Human Physiology', 'nsmq-bio-physiology', 'Functions of the human body', 'Human physiology studies how the body''s organ systems work together to maintain life and health.', '["Homeostasis", "Nervous system", "Circulatory system", "Respiratory system"]', 4, '2026-08-04T00:00:00.000Z');
INSERT OR IGNORE INTO topics (id, subject_id, parent_id, name, slug, description, theory_content, key_formulas, display_order, created_at) VALUES ('topic_nsmq_bio_biochemistry', 'subj_nsmq_biology', NULL, 'Biochemistry', 'nsmq-bio-biochemistry', 'Chemical processes in living organisms', 'Biochemistry explores the chemical reactions that occur within living cells, including metabolism and enzyme function.', '["ATP → ADP + P + energy", "Photosynthesis: 6CO₂ + 6H₂O → C₆H₁₂O₆ + 6O₂", "Cellular respiration"]', 5, '2026-08-04T00:00:00.000Z');
INSERT OR IGNORE INTO topics (id, subject_id, parent_id, name, slug, description, theory_content, key_formulas, display_order, created_at) VALUES ('topic_nsmq_math_quadratic', 'subj_nsmq_math', 'topic_nsmq_math_algebra', 'Quadratic Equations', 'nsmq-math-quadratic', 'Solving and graphing quadratic equations', 'A quadratic equation has the standard form ax² + bx + c = 0. Solutions can be found using factoring, completing the square, or the quadratic formula.', '["x = (-b ± √(b²-4ac)) / 2a", "Sum of roots = -b/a", "Product of roots = c/a", "Discriminant Δ = b² - 4ac"]', 1, '2026-08-04T00:00:00.000Z');
INSERT OR IGNORE INTO topics (id, subject_id, parent_id, name, slug, description, theory_content, key_formulas, display_order, created_at) VALUES ('topic_nsmq_phys_kinematics', 'subj_nsmq_physics', 'topic_nsmq_phys_mechanics', 'Kinematics', 'nsmq-phys-kinematics', 'Description of motion without considering forces', 'Kinematics describes motion using concepts of displacement, velocity, and acceleration without reference to the forces causing the motion.', '["Average velocity = Δs/Δt", "Instantaneous velocity = ds/dt", "Acceleration = dv/dt", "Range = u²sin2θ/g"]', 1, '2026-08-04T00:00:00.000Z');
CREATE TABLE IF NOT EXISTS _migration_517_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_517_guard;
INSERT INTO _migration_517_guard(valid) SELECT CASE WHEN EXISTS (SELECT 1 FROM exam_types WHERE id = 'exam_nsmq') AND (SELECT COUNT(*) FROM subjects WHERE id IN ('subj_nsmq_math', 'subj_nsmq_physics', 'subj_nsmq_chemistry', 'subj_nsmq_biology') AND exam_type_id = 'exam_nsmq') = 4 AND (SELECT COUNT(*) FROM topics t JOIN subjects s ON s.id = t.subject_id WHERE t.id IN ('topic_nsmq_math_algebra', 'topic_nsmq_math_quadratic', 'topic_nsmq_math_geometry', 'topic_nsmq_math_trigonometry', 'topic_nsmq_math_statistics', 'topic_nsmq_math_calculus', 'topic_nsmq_phys_mechanics', 'topic_nsmq_phys_kinematics', 'topic_nsmq_phys_electricity', 'topic_nsmq_phys_waves', 'topic_nsmq_phys_thermodynamics', 'topic_nsmq_phys_modern_physics', 'topic_nsmq_chem_atomic', 'topic_nsmq_chem_bonding', 'topic_nsmq_chem_stoichiometry', 'topic_nsmq_chem_equilibrium', 'topic_nsmq_chem_organic', 'topic_nsmq_chem_electrochemistry', 'topic_nsmq_bio_cells', 'topic_nsmq_bio_genetics', 'topic_nsmq_bio_ecology', 'topic_nsmq_bio_physiology', 'topic_nsmq_bio_biochemistry') AND s.exam_type_id = 'exam_nsmq') = 23 THEN 1 ELSE 0 END;
DROP TABLE _migration_517_guard;
